import java.util.*;
import java.io.*;

public class _1426_E_Variant2 {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int total = Integer.parseInt(br.readLine());
        String[] firstLine = br.readLine().split(" ");
        String[] secondLine = br.readLine().split(" ");
        int[] a = new int[3], b = new int[3];
        for (int i = 0; i < 3; i++) {
            a[i] = Integer.parseInt(firstLine[i]);
        }
        for (int i = 0; i < 3; i++) {
            b[i] = Integer.parseInt(secondLine[i]);
        }
        int max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        int min = 0, leftover = 0;
        if (a[0] >= b[0] + b[2]) {
            min += b[0] + b[2];
        } else {
            min += a[0];
            leftover = b[0] + b[2] - a[0];
        }
        int scissors = 0;
        int supply = Math.min(b[0], leftover);
        if (supply >= a[1]) {
            min += a[1];
            leftover -= a[1];
            scissors = b[1];
        } else {
            min += supply;
            leftover -= supply;
            int need = a[1] - supply;
            if (b[1] >= need) {
                scissors = b[1] - need;
                min += need;
            } else {
                min += b[1];
            }
        }
        min += Math.min(a[2], scissors + Math.min(leftover, b[2]));
        System.out.println((total - min) + " " + max);
        br.close();
    }
}
